        if (style === 'beat') for (let k = 0; k < 16; k++) ccSet('bass', (b + (k >> 2)) * BAR + (k & 3) * 480, 1, k % 2 ? 100 : 10);
        if (style === 'half') for (let k = 0; k < 8; k++) ccSet('bass', (b + (k >> 1)) * BAR + (k & 1) * 960, 1, k % 2 ? 0 : 96);
        if (style === 'swell') ccRamp('bass', b, 4, 1, 0, 120, f => f * f);
