        const st = Math.floor(i / q), ph = Math.floor(i / 8);
        return {
          base: 'main', kick: st === 0 && (gs === 'ukg' || gs === 'sg') ? 'none' : 'base', snare: st >= 2,
          hats: st === 0 ? (gs === 'ch' || gs === 'gh' ? 'offbeat' : 'eighths') : 'base', percBase: st >= 1,
          lib: st >= 1 ? PC_.slice(0, Math.min(3, st)).map((l, k) => [l, k + ph]) : [],
          ghosts: st >= 3 ? 0.12 : 0, fill: i % 8 === 7 ? (i === n - 1 ? 'big' : pick(FILLW[gs])) : null, vel: 0.8 + 0.2 * i / n
        };
