      const rb = withB(o.rh);
      place('chords', M.chordsB, b0, n, { vel: f => 0.5 + 0.5 * f, xf: () => [reharm(rb)] }); ccRamp('chords', b0, n, 74, 35, 127);
      place('lead', M.leadA, b0 + n / 2, n / 2, { vel: f => 0.45 + 0.45 * f, xf: () => [thin, snapTo(rb)] });
      if (g === 'sg') { place('bass', M.bassB, b0 + n / 2, n / 2, { vel: f => 0.6 + 0.4 * f }); ccRamp('bass', b0 + n / 2, n / 2, 74, 20, 127); ccRamp('bass', b0 + n / 2, n / 2, 1, 0, 100); }
      else if (g === 'mth') place('bass', M.bassA, b0, n / 2, { xf: () => [thin] });
      for (let i = 0; i < n; i++) arpBar(b0 + i, st => harm(b0 + i, st, rb), i < n / 2 ? 8 : 16, 'up', 0.35 + 0.6 * i / n, 60 + Math.floor(i * 12 / n));
      ccRamp('arp', b0, n, 74, 30, 127);
