      fx('downlifter', b0 * BAR, 2 * BAR, 96);
      drumPhrase(b0, n, i => ({ base: 'main', kick: 'none', snare: false, hats: 'offbeat', percBase: true, lib: [[PC_[0], 3]], vel: 0.6 + 0.3 * i / n, fill: i === n - 1 ? 'roll' : null }));
