      ccRamp('bass', b0, n / 2, 74, 40, 120, f => f * f); ccRamp('bass', b0 + n / 2, n / 2, 74, 120, 55); ccRamp('bass', b0, n, 71, 60, 115);
      stabPhrase(b0 + n / 2, n / 2, withB(null), 0.7, 3);
